-- Fichas iniciais de avaliação (Anamnese, Avaliação postural e Ficha de inscrição de
-- Dançaterapia), as mesmas de starterAssessmentTemplates em packages/contracts. Viram modelos
-- comuns da clínica (editáveis, versionados e arquiváveis). Idempotente: não duplica se a
-- clínica já tiver um modelo com o mesmo nome.
WITH starter(name, specialty, fields) AS (VALUES
  ('Anamnese', 'Fisioterapia', '[{"key":"objetivo","label":"Objetivo","type":"long_text","required":false},{"key":"atividades","label":"Pratica atividades físicas?","type":"select","options":["Sim","Não","Passado"],"required":false},{"key":"atividades_quais","label":"Quais atividades?","type":"text","required":false},{"key":"queixa_principal","label":"Queixa principal","type":"long_text","required":false},{"key":"queixa_secundaria","label":"Queixa secundária","type":"long_text","required":false},{"key":"diagnostico_medico","label":"Diagnóstico médico","type":"long_text","required":false},{"key":"historia_pregressa","label":"História pregressa de doenças","type":"long_text","required":false},{"key":"avaliacao_postural","label":"Avaliação postural","type":"long_text","required":false},{"key":"forca_muscular","label":"Força muscular","type":"long_text","required":false},{"key":"amplitude_movimento","label":"Amplitude do movimento","type":"long_text","required":false},{"key":"perimetria_exames","label":"Perimetria/exames","type":"long_text","required":false},{"key":"alergias_cirurgias","label":"Alergias/cirurgias","type":"long_text","required":false},{"key":"medicamentos","label":"Medicamentos em uso","type":"long_text","required":false},{"key":"historico_familiar","label":"Histórico familiar","type":"long_text","required":false},{"key":"restricoes","label":"Restrições","type":"long_text","required":false},{"key":"observacoes_gerais","label":"Observações gerais","type":"long_text","required":false}]'::jsonb),
  ('Avaliação postural', 'Fisioterapia', '[{"key":"secao_fisico","label":"Físico-corporal","type":"section","required":false},{"key":"pressao_arterial","label":"Pressão arterial","type":"text","required":false},{"key":"peso","label":"Peso corporal","type":"number","unit":"kg","min":0,"required":false},{"key":"altura","label":"Altura","type":"number","unit":"m","min":0,"max":3,"required":false},{"key":"secao_anterior","label":"Vista anterior","type":"section","required":false},{"key":"anterior_cabeca","label":"Cabeça","type":"text","required":false},{"key":"anterior_ombros","label":"Altura dos ombros","type":"text","required":false},{"key":"anterior_maos","label":"Altura das mãos","type":"text","required":false},{"key":"anterior_rotacao_tronco","label":"Rotação do tronco","type":"text","required":false},{"key":"anterior_angulo_tales","label":"Ângulo de Tales","type":"text","required":false},{"key":"anterior_cicatriz_umbilical","label":"Cicatriz umbilical","type":"text","required":false},{"key":"anterior_crista_iliaca","label":"Altura da crista ilíaca","type":"text","required":false},{"key":"anterior_joelhos","label":"Joelhos","type":"text","required":false},{"key":"anterior_observacoes","label":"Observações da vista anterior","type":"long_text","required":false},{"key":"secao_posterior","label":"Vista posterior","type":"section","required":false},{"key":"posterior_escapulas","label":"Altura das escápulas","type":"text","required":false},{"key":"posterior_escapulas_aladas","label":"Escápulas aladas","type":"text","required":false},{"key":"posterior_cervical","label":"Coluna cervical","type":"text","required":false},{"key":"posterior_toracica","label":"Coluna torácica","type":"text","required":false},{"key":"posterior_lombar","label":"Coluna lombar","type":"text","required":false},{"key":"posterior_observacoes","label":"Observações da vista posterior","type":"long_text","required":false},{"key":"secao_lateral","label":"Vista lateral","type":"section","required":false},{"key":"lateral_cabeca","label":"Cabeça","type":"text","required":false},{"key":"lateral_cervical","label":"Cervical","type":"text","required":false},{"key":"lateral_ombros","label":"Ombros","type":"text","required":false},{"key":"lateral_toracica","label":"Coluna torácica","type":"text","required":false},{"key":"lateral_lombar","label":"Coluna lombar","type":"text","required":false},{"key":"lateral_abdomen","label":"Abdômen","type":"text","required":false},{"key":"lateral_pelve","label":"Pelve","type":"text","required":false},{"key":"lateral_joelhos","label":"Joelhos","type":"text","required":false},{"key":"secao_observacoes","label":"Conclusão","type":"section","required":false},{"key":"observacoes_gerais","label":"Observações gerais","type":"long_text","required":false}]'::jsonb),
  ('Ficha de inscrição — Dançaterapia e Aula de Ritmos', 'Dançaterapia', '[{"key":"objetivos","label":"Qual é o seu principal objetivo com as aulas?","type":"multiselect","options":["Melhorar a mobilidade","Praticar uma atividade física","Reduzir o estresse e a ansiedade","Trabalhar a coordenação e o equilíbrio","Socializar e conhecer novas pessoas","Dançar e se divertir"],"required":false},{"key":"objetivo_outro","label":"Outro objetivo","type":"text","required":false},{"key":"saude","label":"Possui alguma dor, problema de saúde ou doença preexistente?","type":"long_text","required":false},{"key":"cirurgias_lesoes","label":"Já realizou alguma cirurgia ou teve alguma lesão importante?","type":"long_text","required":false},{"key":"limitacoes","label":"Existe alguma limitação ou informação importante que eu precise saber antes das aulas?","type":"long_text","required":false}]'::jsonb)
)
INSERT INTO assessment_templates (id, clinic_id, name, specialty, fields, version, status, family_id)
SELECT x.id, x.clinic_id, x.name, x.specialty, x.fields, 1, 'published', x.id
FROM (
  SELECT gen_random_uuid() AS id, c.id AS clinic_id, s.name, s.specialty, s.fields
  FROM clinics c CROSS JOIN starter s
  WHERE NOT EXISTS (
    SELECT 1 FROM assessment_templates t WHERE t.clinic_id = c.id AND t.name = s.name
  )
) x;
